package com.witchersbestiary.client.compat;
import net.fabricmc.loader.api.FabricLoader;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;import net.minecraft.client.option.KeyBinding;import net.minecraft.client.util.InputUtil;import net.minecraft.text.Text;import org.lwjgl.glfw.GLFW;import java.util.Arrays;
/** One-time migration of the proven legacy K/K collision; custom bindings and foreign controls stay intact. */
public final class SkillTreeKeyCompat {
 public static void initialize(){if(!FabricLoader.getInstance().isModLoaded("puffish_skills"))return;ClientTickEvents.END_CLIENT_TICK.register(new ClientTickEvents.EndTick(){private boolean checked;public void onEndTick(net.minecraft.client.MinecraftClient client){if(checked||client.player==null)return;checked=true;var keys=client.options.allKeys;var dodge=Arrays.stream(keys).filter(k->k.getTranslationKey().equals("key.witchersbestiary.fist_dodge")).findFirst().orElse(null);var tree=Arrays.stream(keys).filter(k->k.getTranslationKey().equals("key.puffish_skills.open")).findFirst().orElse(null);if(dodge==null||tree==null)return;var bound=KeyBindingHelper.getBoundKeyOf(dodge);if(bound.getCode()!=GLFW.GLFW_KEY_K||!bound.equals(KeyBindingHelper.getBoundKeyOf(tree)))return;for(int candidate:new int[]{GLFW.GLFW_KEY_LEFT_ALT,GLFW.GLFW_KEY_RIGHT_ALT,GLFW.GLFW_KEY_F8,GLFW.GLFW_KEY_F9}){var key=InputUtil.fromKeyCode(candidate,0);if(Arrays.stream(keys).anyMatch(k->key.equals(KeyBindingHelper.getBoundKeyOf(k))))continue;dodge.setBoundKey(key);KeyBinding.updateKeysByCode();client.options.write();client.player.sendMessage(Text.translatable("compat.witchersbestiary.skill_tree_dodge",dodge.getBoundKeyLocalizedText()),false);return;}client.player.sendMessage(Text.translatable("compat.witchersbestiary.skill_tree_conflict"),false);}});}
}
